import {BALANCE as B,ZOMBIES,ELITE_MODIFIERS} from './data.js';

export const BOSSES={
 crusher:{id:'crusher',name:'THE CRUSHER',hp:4200,speed:.28,damage:150,attackInterval:1.35,color:'#66755b',threatCost:18,ability:'CHARGE ATTACK',abilityDescription:'Rompa sua linha antes que a investida alcance o jardim.',chargeCooldown:9,telegraph:1.8,chargeSpeed:4.2,hpScale:.62,damageScale:.24},
 collector:{id:'collector',name:'THE COLLECTOR',hp:3900,speed:.38,damage:88,attackInterval:1.05,color:'#786a49',threatCost:17,ability:'SUN THIEF',abilityDescription:'Colete Suns no campo antes que ele os roube.',stealRadius:3.8,stealCooldown:4.8,stealTelegraph:.8,hpScale:.46,damageScale:.18},
 foreman:{id:'foreman',name:'THE FOREMAN',hp:4400,speed:.31,damage:78,attackInterval:1.1,color:'#596d66',threatCost:19,ability:'COMMAND AURA',abilityDescription:'Quebre a horda antes que a aura e os reforços cresçam.',auraRadius:3.4,moveAura:1.18,attackAura:1.15,reinforcementCooldown:10,reinforcementBudget:13,hpScale:.5,damageScale:.16}
};
export const BOSS_ROTATION=['crusher','collector','foreman'];
export const ELITE_ORDER=Object.keys(ELITE_MODIFIERS);
const THEMES={
 rush:{id:'rush',name:'RUSH WAVE',minWave:5,weights:{sprinter:3,normal:1.2}},
 heavy:{id:'heavy',name:'HEAVY PUSH',minWave:8,weights:{brute:2.8,buckethead:1.8,normal:.8}},
 plague:{id:'plague',name:'PLAGUE WAVE',minWave:12,weights:{sporekeeper:2.2,volatile:2.3,conehead:1.2}},
 horde:{id:'horde',name:'HORDE WAVE',minWave:6,weights:{normal:2.4,conehead:1.6,sprinter:1.15}}
};

export const isBossWave=n=>n>0&&n%B.bossEvery===0;
export function selectBossForWave(wave,previousBoss=null){if(!isBossWave(wave))return null;const appearance=Math.floor(wave/B.bossEvery);let id=BOSS_ROTATION[(appearance-1)%BOSS_ROTATION.length];if(appearance>3&&id===previousBoss)id=BOSS_ROTATION[(BOSS_ROTATION.indexOf(id)+1)%BOSS_ROTATION.length];return id}
export function threatBudget(n){return isBossWave(n)?Math.round(14+n*1.5):Math.round(B.waves.baseBudget+(n-1)*B.waves.budgetGrowth+Math.floor((n-1)/10)*B.waves.chapterGrowth)}
export function available(n){return ZOMBIES.filter(z=>n>=z.unlockWave)}
function eliteChance(n){if(n<15)return 0;return Math.min(.18,.05+(n-15)*.004)}
function chooseTheme(n,rng,isBoss){if(isBoss||n<5||rng()>.27)return null;const options=Object.values(THEMES).filter(t=>n>=t.minWave);return options[Math.floor(rng()*options.length)]||null}
function weightedPick(pool,theme,rng){const weights=pool.map(z=>z.weight*(theme?.weights[z.id]||1)),total=weights.reduce((a,b)=>a+b,0);let roll=rng()*total;for(let i=0;i<pool.length;i++){roll-=weights[i];if(roll<=0)return pool[i]}return pool[0]}
function eliteFor(n,z,rng){if(n<15||rng()>=eliteChance(n))return null;const valid=ELITE_ORDER.filter(id=>!(id==='armored'&&z.id==='brute')&&!(id==='toxic'&&z.id==='volatile')&&!(id==='regenerating'&&z.id==='sporekeeper'));return valid[Math.floor(rng()*valid.length)]||null}
function capFor(z,budget){if(z.id==='brute')return Math.max(1,Math.floor(budget/15));if(z.id==='sporekeeper')return Math.max(1,Math.min(2,Math.floor(budget/13)));if(z.id==='volatile')return Math.max(2,Math.min(4,Math.floor(budget/9)));return Math.max(z.groupCap||99,1)*3}
function compositionFor(n,budget,rng,theme=null){const entries=new Map(),counts=Object.fromEntries(ZOMBIES.map(z=>[z.id,0]));let left=budget,guard=300;const add=(z,elite=null)=>{const multiplier=elite?ELITE_MODIFIERS[elite].threatMultiplier:1,cost=z.threatCost*multiplier;if(cost>left+.001)return false;const key=z.id+':'+(elite||'base'),current=entries.get(key)||{type:z.id,name:z.name,count:0,threatCost:z.threatCost,elite,role:z.role};current.count++;entries.set(key,current);counts[z.id]++;left-=cost;return true},debuts={3:'conehead',4:'sprinter',5:'buckethead',8:'brute',11:'sporekeeper',12:'volatile'},debut=ZOMBIES.find(z=>z.id===debuts[n]);if(debut){const amount=debut.id==='sprinter'?Math.min(3,Math.floor(left/debut.threatCost)):1;for(let i=0;i<amount;i++)add(debut)}else if(n>12){const specials=available(n).filter(z=>!['normal','conehead','buckethead'].includes(z.id)),favored=theme&&specials.find(z=>(theme.weights[z.id]||0)>1)||specials[n%specials.length];if(favored)add(favored)}const candidates=available(n).filter(z=>z.id!=='normal'&&!counts[z.id]),variety=n>=12?2:n>=8?1:n>=4?1:0;for(let i=0;i<variety&&candidates.length;i++){const z=candidates[(n+i)%candidates.length];add(z)}while(left>=1&&guard--){const pool=available(n).filter(z=>z.threatCost<=left+.001&&counts[z.id]<capFor(z,budget));if(!pool.length)break;const z=weightedPick(pool,theme,rng);let elite=eliteFor(n,z,rng),cost=z.threatCost*(elite?ELITE_MODIFIERS[elite].threatMultiplier:1);if(cost>left+.001)elite=null;add(z,elite)}return [...entries.values()]}
function takeFromBag(bag,predicate){const i=bag.findIndex(predicate);return i<0?null:bag.splice(i,1)[0]}
function themedGroups(bag,rng){const groups=[];const add=(items,afterDelay=2.8)=>groups.push({enemies:pack(items),insideDelay:B.waves.insideDelay,afterDelay});if(rng()<.7){const support=takeFromBag(bag,x=>x.type==='sporekeeper'),guard=takeFromBag(bag,x=>x.type==='buckethead'||x.type==='conehead'),guard2=takeFromBag(bag,x=>x.type==='conehead'||x.type==='normal');if(support&&guard)add([guard,guard2, support].filter(Boolean));else bag.push(...[support,guard,guard2].filter(Boolean))}if(rng()<.7){const brute=takeFromBag(bag,x=>x.type==='brute');if(brute){const escort=[brute];for(let i=0;i<3;i++){const n=takeFromBag(bag,x=>x.type==='normal');if(n)escort.push(n)}add(escort,3.1)}}if(rng()<.65){const volatile=takeFromBag(bag,x=>x.type==='volatile');if(volatile){const rush=[volatile];for(let i=0;i<2;i++){const s=takeFromBag(bag,x=>x.type==='sprinter');if(s)rush.push(s)}add(rush)}}if(rng()<.65){const packItems=[];for(let i=0;i<3;i++){const s=takeFromBag(bag,x=>x.type==='sprinter');if(s)packItems.push(s)}if(packItems.length>=2)add(packItems,2.2);else bag.push(...packItems)}return groups}
function pack(items){const packed=[];for(const item of items){const found=packed.find(x=>x.type===item.type&&x.elite===item.elite);found?found.count++:packed.push({...item,count:1})}return packed}
function makeGroups(enemies,rng,bossId=null){const bag=[];for(const e of enemies)for(let i=0;i<e.count;i++)bag.push({type:e.type,elite:e.elite||null});for(let i=bag.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[bag[i],bag[j]]=[bag[j],bag[i]]}const groups=[];if(bossId)groups.push({enemies:[{type:'boss',bossId,count:1}],insideDelay:0,afterDelay:2.8});groups.push(...themedGroups(bag,rng));let at=0;while(at<bag.length){const size=Math.min(bag.length-at,2+Math.floor(rng()*4));groups.push({enemies:pack(bag.slice(at,at+size)),insideDelay:B.waves.insideDelay,afterDelay:B.waves.groupDelay});at+=size}return groups}
export function createWavePlan(waveNumber,spawnEdges=['north'],rng=Math.random,previousBoss=null){const type=isBossWave(waveNumber)?'boss':'normal',budget=threatBudget(waveNumber),bossId=selectBossForWave(waveNumber,previousBoss),theme=chooseTheme(waveNumber,rng,type==='boss'),escortBudget=type==='boss'?Math.max(5,budget-BOSSES[bossId].threatCost):budget,enemies=compositionFor(waveNumber,escortBudget,rng,theme),edges=[...new Set(spawnEdges.length?spawnEdges:['north'])],spent=enemies.reduce((n,e)=>n+e.count*e.threatCost*(e.elite?ELITE_MODIFIERS[e.elite].threatMultiplier:1),0)+(bossId?BOSSES[bossId].threatCost:0);return {waveNumber,type,bossId,boss:bossId?BOSSES[bossId]:null,theme,enemies,spawnEdges:edges,spawnGroups:makeGroups(enemies,rng,bossId),threatBudget:budget,spentThreat:Math.round(spent*100)/100}}
export function flattenGroups(plan){const out=[];for(const group of plan.spawnGroups){const flat=[];for(const item of group.enemies)for(let i=0;i<item.count;i++)flat.push({...item});for(let i=0;i<flat.length;i++)out.push({...flat[i],delay:i===flat.length-1?group.afterDelay:group.insideDelay})}return out}
